const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Acre, Brazil (approximate bounding box)
  var acre = ee.Geometry.Polygon([
    [-73.5, -11.0],
    [-67.5, -11.0],
    [-67.5, -7.0],
    [-73.5, -7.0]
  ]);

  // 2. Define date ranges for comparison
  var julyStart = '2005-07-20';
  var julyEnd = '2005-08-05';  // Late July period
  var septStart = '2005-09-20';
  var septEnd = '2005-10-05';  // Late September period

  // Day-of-year ranges (approximately)
  var julyDoyRange = [200, 220];  // July 20 ≈ day 200, August 5 ≈ day 217
  var septDoyRange = [260, 280];  // Sept 20 ≈ day 263, Oct 5 ≈ day 278

  // 3. Load MODIS Burned Area collection
  var burnedArea = ee.ImageCollection('MODIS/006/MCD64A1')
    .filterBounds(acre)
    .filterDate('2005-01-01', '2005-12-31');

  // Check if collection has any data
  var collectionSize = burnedArea.size().getInfo();
  print('Total 2005 burned area images:', collectionSize);

  if (collectionSize === 0) {
    print('No burned area data found for 2005.');
    print('<answer>C1</answer>');
    return;
  }

  // 4. Process July period
  var julyBurned = burnedArea.filterDate(julyStart, julyEnd);
  var julyCount = julyBurned.size().getInfo();
  print('July period images:', julyCount);

  var julyBurnedPixels = 0;
  if (julyCount > 0) {
    // Create mask for burns within day-of-year range
    var julyMask = julyBurned.map(function(image) {
      var burnDate = image.select('BurnDate');
      return burnDate.gte(julyDoyRange[0]).and(burnDate.lte(julyDoyRange[1]));
    });

    // Sum all burned pixels in the collection
    var julySum = julyMask.sum();

    // Count burned pixels
    var julyStats = julySum.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: acre,
      scale: 1000,
      maxPixels: 1e9
    });

    julyBurnedPixels = julyStats.get('BurnDate').getInfo();
    print('July burned pixels:', julyBurnedPixels);
  }

  // 5. Process September period
  var septBurned = burnedArea.filterDate(septStart, septEnd);
  var septCount = septBurned.size().getInfo();
  print('September period images:', septCount);

  var septBurnedPixels = 0;
  if (septCount > 0) {
    // Create mask for burns within day-of-year range
    var septMask = septBurned.map(function(image) {
      var burnDate = image.select('BurnDate');
      return burnDate.gte(septDoyRange[0]).and(burnDate.lte(septDoyRange[1]));
    });

    // Sum all burned pixels in the collection
    var septSum = septMask.sum();

    // Count burned pixels
    var septStats = septSum.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: acre,
      scale: 1000,
      maxPixels: 1e9
    });

    septBurnedPixels = septStats.get('BurnDate').getInfo();
    print('September burned pixels:', septBurnedPixels);
  }

  // 6. Check for data issues
  if (julyCount === 0 || septCount === 0) {
    print('Missing data for one or both periods.');
    print('<answer>C1</answer>');
    return;
  }

  if (julyBurnedPixels === null || septBurnedPixels === null ||
      isNaN(julyBurnedPixels) || isNaN(septBurnedPixels)) {
    print('Calculation failed (null/NaN result).');
    print('<answer>C3</answer>');
    return;
  }

  // 7. Compare and output result
  print('Comparison: July=' + julyBurnedPixels + ', Sept=' + septBurnedPixels);

  if (septBurnedPixels > julyBurnedPixels) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
